impl SseEncode for crate::api::error::MadarError {
    // Codec=Sse (Serialization based), see doc to use other codecs
    fn sse_encode(self, serializer: &mut flutter_rust_bridge::for_generated::SseSerializer) {
        match self {
            crate::api::error::MadarError::Offline { detail } => {
                <i32>::sse_encode(0, serializer);
                <String>::sse_encode(detail, serializer);
            }
            crate::api::error::MadarError::Unauthenticated { detail } => {
                <i32>::sse_encode(1, serializer);
                <String>::sse_encode(detail, serializer);
            }
            crate::api::error::MadarError::Forbidden { resource, action } => {
                <i32>::sse_encode(2, serializer);
                <String>::sse_encode(resource, serializer);
                <String>::sse_encode(action, serializer);
            }
            crate::api::error::MadarError::Validation { field, detail } => {
                <i32>::sse_encode(3, serializer);
                <String>::sse_encode(field, serializer);
                <String>::sse_encode(detail, serializer);
            }
            crate::api::error::MadarError::Server {
                status,
                code,
                detail,
            } => {
                <i32>::sse_encode(4, serializer);
                <u16>::sse_encode(status, serializer);
                <String>::sse_encode(code, serializer);
                <String>::sse_encode(detail, serializer);
            }
            crate::api::error::MadarError::Transient { detail } => {
                <i32>::sse_encode(5, serializer);
                <String>::sse_encode(detail, serializer);
            }
            crate::api::error::MadarError::Internal { detail } => {
                <i32>::sse_encode(6, serializer);
                <String>::sse_encode(detail, serializer);
            }
            _ => {
                unimplemented!("");
            }
        }
    }
}

